845		  HB_DIRECTION_IS_VERTICAL (c->buffer->props.direction) !=
846		  bool (subtable->coverage & ChainSubtable::Vertical))
847	        goto skip;
848	
849	      /* Buffer contents is always in logical direction.  Determine if
850	       * we need to reverse before applying this subtable.  We reverse
851	       * back after if we did reverse indeed.
852	       *
853	       * Quoting the spac:
854	       * """
855	       * Bits 28 and 30 of the coverage field control the order in which
856	       * glyphs are processed when the subtable is run by the layout engine.
857	       * Bit 28 is used to indicate if the glyph processing direction is
858	       * the same as logical order or layout order. Bit 30 is used to
859	       * indicate whether glyphs are processed forwards or backwards within
860	       * that order.
861	
862			Bit 30	Bit 28	Interpretation for Horizontal Text
863			0	0	The subtable is processed in layout order
864					(the same order as the glyphs, which is
865					always left-to-right).
866			1	0	The subtable is processed in reverse layout order
867					(the order opposite that of the glyphs, which is
868					always right-to-left).
869			0	1	The subtable is processed in logical order
870					(the same order as the characters, which may be
871					left-to-right or right-to-left).
872			1	1	The subtable is processed in reverse logical order
873					(the order opposite that of the characters, which
874					may be right-to-left or left-to-right).
875	       */
876	      reverse = subtable->coverage & ChainSubtable::Logical ?
877			bool (subtable->coverage & ChainSubtable::Descending) :
878			bool (subtable->coverage & ChainSubtable::Descending) !=
879			HB_DIRECTION_IS_BACKWARD (c->buffer->props.direction);

